import React, { useMemo, useState } from "react";
import axios from "axios";
import UploadForm from "./components/UploadForm";
import Results from "./components/Results";

export default function App() {
  const [file, setFile] = useState(null);
  const [videoUrl, setVideoUrl] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const backendBase = useMemo(() => {
    // Dev: CRA proxy handles /api calls. For download links we want absolute.
    return window.location.hostname === "localhost" ? "http://localhost:8000" : "";
  }, []);

  const onPickFile = (f) => {
    setError(null);
    setResult(null);
    setFile(f);
    if (videoUrl) URL.revokeObjectURL(videoUrl);
    setVideoUrl(f ? URL.createObjectURL(f) : null);
  };

  const onAnalyze = async () => {
    if (!file) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const form = new FormData();
      form.append("video", file);
      const res = await axios.post("/api/analyze", form, {
        headers: { "Content-Type": "multipart/form-data" },
        timeout: 10 * 60 * 1000,
      });
      setResult(res.data);
    } catch (e) {
      setError(e?.response?.data?.error || e.message || "Request failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h2 style={{ marginTop: 0 }}>Inter-Frame Video Forgery Detection (CPU Demo)</h2>
        <p style={{ marginTop: 0, color: "#555" }}>
          Upload a video to detect frame deletion and interpolation using optical flow + texture features.
        </p>
        <UploadForm file={file} onPickFile={onPickFile} onAnalyze={onAnalyze} loading={loading} />
        {error && <div style={styles.error}>{error}</div>}
      </div>

      {result && (
        <div style={styles.card}>
          <Results result={result} videoUrl={videoUrl} backendBase={backendBase} />
        </div>
      )}

      <div style={styles.footer}>
        Backend: Flask + OpenCV Farneback + LBP texture | Frontend: React + Chart.js
      </div>
    </div>
  );
}

const styles = {
  page: {
    fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif",
    maxWidth: 1100,
    margin: "24px auto",
    padding: "0 16px",
  },
  card: {
    background: "#fff",
    border: "1px solid #e6e6e6",
    borderRadius: 12,
    padding: 16,
    marginBottom: 16,
    boxShadow: "0 2px 10px rgba(0,0,0,0.04)",
  },
  error: {
    marginTop: 12,
    padding: 12,
    borderRadius: 8,
    background: "#fff0f0",
    border: "1px solid #ffd0d0",
    color: "#8a1f1f",
  },
  footer: {
    color: "#777",
    fontSize: 12,
    marginTop: 8,
    textAlign: "center",
  },
};
